     \"code\": \"OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"statement\": \"No se especifica en qué momento de la negociación existe una oferta que el cliente puede aceptar.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"CLIENT_CHANNEL_AND_SCOPE\",\n      \"statement\": \"No se indican los canales, pantallas o segmentos de clientes del marketplace incluidos en el piloto.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"INSTALLMENT_MEANING\",\n      \"statement\": \"No se define qué representa el monto de la cuota ni en qué situaciones corresponde distinguirlo del ahorro.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"ABANDONMENT_EVIDENCE\",\n      \"statement\": \"No se aportan mediciones, causas verificadas ni alcance del abandono mencionado.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"COMPREHENSION_CRITERION\",\n      \"statement\": \"No se define cómo se determinará que la diferencia entre ahorro y cuota resulta clara para el cliente.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"PILOT_DEADLINE\",\n      \"statement\": \"Se indica urgencia, pero no una fecha o hito preciso del piloto.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    }\n  ],\n  \"no_solution_inferred\": true\n}\n\n\n<<<ITEM_A>>>\n{\n  \"schema_version\": \"A2_CLASSIFICATION_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"classification\": {\n    \"target_granularity\": \"Capacidad funcional de comunicación y comprensión del ahorro en la negociación de deuda, antes de aceptar una oferta. Pantalla, canal, segmento y alcance exactos no identificados.\",\n    \"change_type\": \"Cambio funcional orientado a claridad de información económica previa a la aceptación de una oferta. No se determina si corresponde modificar una capacidad existente o introducir una nueva.\",\n    \"depth\": \"L1\",\n    \"authority_state\": \"UNKNOWN\",\n    \"implementation_state\": \"EXISTING\"\n  },\n  \"signals\": {\n    \"materiality_level\": \"HIGH\",\n    \"scope_bounded\": \"UNKNOWN\",\n    \"authority_state\": \"UNKNOWN\",\n    \"reversibility_state\": \"UNKNOWN\",\n    \"currentness_decision\": \"UNKNOWN_FAIL_CLOSED\",\n    \"material_contradiction\": false,\n    \"known_cross_scope_impact\": \"UNKNOWN\",\n    \"unresolved_material_signal_count\": 5,\n    \"required_specialist_count\": 0\n  },\n  \"signal_sources\": [\n    {\n      \"signal\": \"materiality_level\",\n      \"source_ref\": \"ambiguity:SAVINGS_MEANING_AND_BASIS\"\n    },\n    {\n      \"signal\": \"scope_bounded\",\n      \"source_ref\": \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\"\n    },\n    {\n      \"signal\": \"authority_state\",\n      \"source_ref\": \"supabase://public.lf_eventos/99999\"\n    },\n    {\n      \"signal\": \"reversibility_state\",\n      \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n    },\n    {\n      \"signal\": \"currentness_decision\",\n      \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n    },\n    {\n      \"signal\": \"material_contradiction\",\n      \"source_ref\": \"supabase://public.lf_eventos/20843\"\n    },\n    {\n      \"signal\": \"known_cross_scope_impact\",\n      \"source_ref\": \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\"\n    },\n    {\n      \"signal\": \"unresolved_material_signal_count\",\n      \"source_ref\": \"supabase://public.lf_eventos/20843\"\n    },\n    {\n      \"signal\": \"required_specialist_count\",\n      \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n    }\n  ],\n  \"depth_reason\": \"L3 por materialidad HIGH: la solicitud afecta la comprensión de importes económicos antes de aceptar una oferta de negociación de deuda. La definición del ahorro y su base de comparación son materialmente desconocidas, al igual que el significado de la cuota, el límite entre oferta y aceptación, el alcance del piloto y el criterio de comprensión. Existen cinco ambigüedades explícitamente clasificadas MATERIAL y OPEN. No se observa una contradicción factual explícita, pero tampoco existe evidencia suficiente para determinar alcance entre procesos, autoridad vigente, implementación existente, reversibilidad o actualidad de las fuentes. La cantidad 0 de especialistas refleja únicamente que ninguno está identificado expresamente en el contexto, no que se haya demostrado que no son necesarios. La regla de precedencia exige L3 por materialidad HIGH, independientemente de las demás señales. No se infiere una solución técnica.\",\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n    \"supabase://public.lf_eventos/20843\",\n    \"ambiguity:SAVINGS_MEANING_AND_BASIS\",\n    \"ambiguity:OFFER_AND_ACCEPTANCE_BOUNDARY\",\n    \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\",\n    \"ambiguity:INSTALLMENT_MEANING\",\n    \"ambiguity:COMPREHENSION_CRITERION\"\n  ]\n}\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"A2_CLASSIFICATION_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"classification\": {\n    \"target_granularity\": \"Capacidad funcional de comunicación y comprensión del ahorro en la negociación de deuda, antes de aceptar una oferta. Pantalla, canal, segmento y alcance exactos no identificados.\",\n    \"change_type\": \"Cambio funcional orientado a claridad de información económica previa a la aceptación de una oferta. No se determina si corresponde modificar una capacidad existente o introducir una nueva.\",\n    \"depth\": \"L3\",\n    \"authority_state\": \"UNKNOWN\",\n    \"implementation_state\": \"UNKNOWN\"\n  },\n  \"signals\": {\n    \"materiality_level\": \"HIGH\",\n    \"scope_bounded\": \"UNKNOWN\",\n    \"authority_state\": \"UNKNOWN\",\n    \"reversibility_state\": \"UNKNOWN\",\n    \"currentness_decision\": \"UNKNOWN_FAIL_CLOSED\",\n    \"material_contradiction\": false,\n    \"known_cross_scope_impact\": \"UNKNOWN\",\n    \"unresolved_material_signal_count\": 5,\n    \"required_specialist_count\": 0\n  },\n  \"signal_sources\": [\n    {\n      \"signal\": \"materiality_level\",\n      \"source_ref\": \"ambiguity:SAVINGS_MEANING_AND_BASIS\"\n    },\n    {\n      \"signal\": \"scope_bounded\",\n      \"source_ref\": \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\"\n    },\n    {\n      \"signal\": \"authority_state\",\n      \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n    },\n    {\n      \"signal\": \"reversibility_state\",\n      \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n    },\n    {\n      \"signal\": \"currentness_decision\",\n      \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n    },\n    {\n      \"signal\": \"material_contradiction\",\n      \"source_ref\": \"supabase://public.lf_eventos/20843\"\n    },\n    {\n      \"signal\": \"known_cross_scope_impact\",\n      \"source_ref\": \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\"\n    },\n    {\n      \"signal\": \"unresolved_material_signal_count\",\n      \"source_ref\": \"supabase://public.lf_eventos/20843\"\n    },\n    {\n      \"signal\": \"required_specialist_count\",\n      \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n    }\n  ],\n  \"depth_reason\": \"L3 por materialidad HIGH: la solicitud afecta la comprensión de importes económicos antes de aceptar una oferta de negociación de deuda. La definición del ahorro y su base de comparación son materialmente desconocidas, al igual que el significado de la cuota, el límite entre oferta y aceptación, el alcance del piloto y el criterio de comprensión. Existen cinco ambigüedades explícitamente clasificadas MATERIAL y OPEN. No se observa una contradicción factual explícita, pero tampoco existe evidencia suficiente para determinar alcance entre procesos, autoridad vigente, implementación existente, reversibilidad o actualidad de las fuentes. La cantidad 0 de especialistas refleja únicamente que ninguno está identificado expresamente en el contexto, no que se haya demostrado que no son necesarios. La regla de precedencia exige L3 por materialidad HIGH, independientemente de las demás señales. No se infiere una solución técnica.\",\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n    \"supabase://public.lf_eventos/20843\",\n    \"ambiguity:SAVINGS_MEANING_AND_BASIS\",\n    \"ambiguity:OFFER_AND_ACCEPTANCE_BOUNDARY\",\n    \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\",\n    \"ambiguity:INSTALLMENT_MEANING\",\n    \"ambiguity:COMPREHENSION_CRITERION\"\n  ]\n}\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A2Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales cortas, copiadas LITERALMENTE de la solicitud o del ítem, sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","rules_text":"Clasifica el cambio. No infieras solución técnica. No inventes fuentes: las únicas fuentes válidas son las del contexto (sus source_refs, 'ambiguity:<code>' y 'fact:<fact_code>'); si una señal no tiene fuente en el contexto, su fuente es 'NO_SOURCE_SUPPLIED' y su valor debe ser UNKNOWN/UNRESOLVED. El estado de autoridad y de implementación no se pueden afirmar sin evidencia: usa UNKNOWN. Lo desconocido material nunca puede ser L1. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, classification, signals, signal_sources, depth_reason, evidence_refs. schema_version='A2_CLASSIFICATION_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. classification={target_granularity (texto), change_type (texto), depth (L1|L2|L3), authority_state (EXISTING|NEW|UNKNOWN), implementation_state (EXISTING|NEW|UNKNOWN)}. signals={materiality_level (LOW|MEDIUM|HIGH|UNKNOWN), scope_bounded (TRUE|FALSE|UNKNOWN), authority_state (SUFFICIENT|INSUFFICIENT|UNKNOWN), reversibility_state (DEMONSTRATED|NOT_DEMONSTRATED|UNKNOWN), currentness_decision (CURRENT|CURRENT_REBOUND|STALE_AFFECTED|UNKNOWN_FAIL_CLOSED|UNRESOLVED), material_contradiction (true|false), known_cross_scope_impact (true|false|\"UNKNOWN\"), unresolved_material_signal_count (entero >=0), required_specialist_count (entero >=0)}. signal_sources=lista con UN elemento por cada una de las 9 señales: {signal, source_ref}. Regla de profundidad (precedencia monótona): L3 si materiality_level=HIGH o material_contradiction=true o known_cross_scope_impact=true; L1 solo si materiality LOW, scope_bounded TRUE, authority_state SUFFICIENT, reversibility DEMONSTRATED, currentness CURRENT o CURRENT_REBOUND, known_cross_scope_impact=false y unresolved_material_signal_count=0; en otro caso L2. depth_reason: texto no vacío que justifica la profundidad. evidence_refs: lista no vacía de fuentes válidas del contexto.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A2Q/A2Q_C3","unit":"A2"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"381a76bccf5e26696460897a68a87b1960ad6882c065b0c171953334d54ebcde","decoy_item_id":"ITEM_A","decoy_must_fail_checks":["MATERIAL_UNKNOWN_NOT_L1"],"decoy_sha256":"718d63f57dd53b7468c58c511295d1ae01bca7d94fe950339959dcb315aa49db","real_item_id":"ITEM_B","replacements":[["\"depth\": \"L3\"","\"depth\": \"L1\""],["\"implementation_state\": \"UNKNOWN\"","\"implementation_state\": \"EXISTING\""],["\"signal\": \"authority_state\",\n      \"source_ref\": \"NO_SOURCE_SUPPLIED\"","\"signal\": \"authority_state\",\n      \"source_ref\": \"supabase://public.lf_eventos/99999\""]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A2Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A2Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A2Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A2Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A2Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A2Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A2Q_C2,input}') THEN RAISE EXCEPTION 'A2Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_m#>>'{gpt_native_packets_v1,A2Q_C2,prompt_for_gpt}'))=0 THEN RAISE EXCEPTION 'A2Q_C3_RULES_NOT_FROM_C2_PROMPT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_packet->>'prompt_for_gpt'))=0 THEN RAISE EXCEPTION 'A2Q_C3_RULES_NOT_IN_PROMPT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A2Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A2Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A2Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A2Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A2Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A2Q_C3,packet_sha256}' <> v_packet_sha THEN RAISE EXCEPTION 'A2Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A2Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A2Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A2Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A2Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A2Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A2Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A2Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A2Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A2Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A2Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A2Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a2q_c3_prep$;
COMMIT;
